    NoChangesetConsumed,
    #[error("the changelog was not touched by this commit")]
    ChangelogNotTouched,
    #[error("the manifest is not part of this commit's diff")]
    ManifestNotInDiff,
    #[error("the manifest version does not match the claimed version")]
